// One probe per (product, query). product = venture slug so rows join to
// lane economics. domains = owned URLs to detect our own ranking result.
// Mix of head terms (real search volume, opportunity sizing) and ICP-specific
// phrases (where we could realistically win first).
const probes = [
  { product: 'mm_ctrl', query: 'AI tools for executives', domains: ['ctrl.themindmaker.ai'] },
  { product: 'mm_ctrl', query: 'AI news aggregator', domains: ['ctrl.themindmaker.ai'] },
  { product: 'mm_ctrl', query: 'best AI news app', domains: ['ctrl.themindmaker.ai'] },
  { product: 'mm_ctrl', query: 'cut through AI news noise tool', domains: ['ctrl.themindmaker.ai'] },
  { product: 'fractionl_pulse', query: 'fractional executive', domains: ['pulse.fractionl.ai','fractionl.ai'] },
  { product: 'fractionl_pulse', query: 'hire fractional executive', domains: ['pulse.fractionl.ai','fractionl.ai'] },
  { product: 'fractionl_pulse', query: 'fractional executive platform', domains: ['pulse.fractionl.ai','fractionl.ai'] },
  { product: 'legibility', query: 'MCP server', domains: ['legibility.io','onplinth.io'] },
  { product: 'legibility', query: 'product data API', domains: ['legibility.io','onplinth.io'] },
  { product: 'legibility', query: 'MCP server for product catalog data', domains: ['legibility.io','onplinth.io'] },
];
return [{ json: { probes } }];

const probes = $('Keyword matrix').first().json.probes;
const serperItems = $('Serper rank batch').all().map(i => i.json);
// Serper batch returns one result object per query, in probe order.
let volByKw = {};
try {
  const dfsItems = $('DataForSEO volume').all().map(i => i.json);
  for (const d of dfsItems) {
    const results = (d && d.tasks && d.tasks[0] && d.tasks[0].result) || [];
    for (const r of results) if (r && r.keyword) volByKw[String(r.keyword).toLowerCase()] = (r.search_volume != null ? r.search_volume : null);
  }
} catch (e) {}
const nowIso = new Date().toISOString();
const rows = [];
probes.forEach((p, idx) => {
  const res = serperItems[idx] || {};
  const organic = Array.isArray(res.organic) ? res.organic : [];
  let pos = null;
  for (let i = 0; i < organic.length; i++) {
    const o = organic[i] || {};
    const link = String(o.link || o.url || '').toLowerCase();
    if ((p.domains || []).some(d => link.includes(d))) { pos = (o.position != null ? Number(o.position) : (i + 1)); break; }
  }
  const vol = (p.query.toLowerCase() in volByKw) ? volByKw[p.query.toLowerCase()] : null;
  const band = pos == null ? (organic.length ? 12 : 8)
    : pos <= 3 ? 25
    : pos <= 15 ? 92
    : pos <= 30 ? 55
    : 30;
  const volMult = vol == null ? 1 : Math.min(1 + vol / 500, 4);
  const priority = Math.round(Math.min(band * volMult, 100));
  rows.push({ product: p.product, query: p.query, current_position: pos, search_volume: vol, priority: priority, last_checked_at: nowIso });
});
const ranking = rows.filter(r => r.current_position != null).length;
const striking = rows.filter(r => r.current_position != null && r.current_position >= 4 && r.current_position <= 15).length;
return [{ json: { rows, checked: rows.length, ranking, striking } }];
